from dataclasses import dataclass

@dataclass
class OrderResult:
    order_id: int
    total: float
    user_id: int

def is_valid_order(order):
    return order is not None and \
           order.get('status') == 'pending' and \
           order.get('items') is not None and \
           len(order.get('items')) > 0 and \
           order.get('user_id') is not None

def process_order(order):
    if not is_valid_order(order):
        return None

    total = 0
    for item in order.get('items', []):
        if item.get('price') is None or item.get('quantity') is None:
            return None
        total += item['price'] * item['quantity']

    return OrderResult(order_id=order.get('id'), total=total, user_id=order.get('user_id'))
